  // source/src/Experience/Utils/Debug.js
  var Debug = class _Debug {
    static _instance = null;
    static getInstance() {
      return _Debug._instance || new _Debug();
    }
    experience = Experience.getInstance();
    sizes = Sizes.getInstance();
    constructor() {
      if (_Debug._instance) {
        return _Debug._instance;
      }
      _Debug._instance = this;
      this.active = true;
      if (this.active) {
        this.panel = new Pane({
          title: "Debug",
          container: document.getElementById("debug-panel")
        });
        this.stats = new import_stats.default();
        this.stats.showPanel(0);
      }
    }
    postInit() {
      this.scene = experience.scene;
    }
    createDebugTexture(texture3, world) {
      this.debugTexture = texture3;
      this.world = world;
      this.scene = world.scene;
      this.camera = world.camera.instance;
      const material = new SpriteNodeMaterial({
        map: texture3,
        // depthWrite: false,
        depthTest: false,
        // //blending: THREE.NoBlending
        toneMapped: false
      });
      const sprite = this.sprite = new Sprite(material);
      sprite.center.set(0, 0);
      sprite.renderOrder = 1e4;
      this.scene.add(sprite);
      this._updateSprite();
    }
    _updateSprite() {
      if (!this.debugTexture) return;
      const position = projectNDCTo3D(-1, -1, this.camera, 10);
      this.sprite.position.copy(position);
    }
    resize() {
      this._updateSprite();
    }
    update(deltaTime3) {
      if (this.debugTexture) {
        this._updateSprite();
      }
    }
  };

  // source/src/Experience/Utils/Time.js
  init_define_import_meta_env();
  var Time = class _Time extends EventEmitter {
    static _instance = null;
    static getInstance() {
      return _Time._instance || new _Time();
    }
    constructor() {
      if (_Time._instance) {
        return _Time._instance;
      }
      super();
      _Time._instance = this;
      this.start = Date.now();
      this.current = this.start;
      this.playing = true;
      this.elapsed = 0;
      this.delta = 0.016666666666666666;
      this.deltaSim = 0.016666666666666666;
      this.timeline = gsapWithCSS.timeline({
        paused: true
      });
      window.requestAnimationFrame(() => {
        this.tick();
      });
    }
    tick() {
      const currentTime = Date.now();
      this.delta = (currentTime - this.current) * 1e-3;
      this.deltaSim = Math.min((currentTime - this.current) * 1e-3, 0.016);
      this.current = currentTime;
      this.elapsed = (this.current - this.start) * 1e-3;
      if (this.deltaSim > 0.06) {
        this.deltaSim = 0.06;
      }
      this.timeline.time(this.elapsed);
      this.trigger("tick");
      window.requestAnimationFrame(() => {
        this.tick();
      });
    }
    reset() {
      this.start = Date.now();
      this.current = this.start;
      this.elapsed = 0;
    }
  };

  // source/src/Experience/Renderer.js
  init_define_import_meta_env();

