  // source/src/Experience/Renderer.js
  var Renderer2 = class {
    constructor() {
      this.experience = new Experience();
      this.canvas = this.experience.canvas;
      this.sizes = this.experience.sizes;
      this.debug = this.experience.debug;
      this.resources = this.experience.resources;
      this.html = this.experience.html;
      this.setInstance();
      this.setDebug();
    }
    postInit() {
      this.camera = this.experience.mainCamera.instance;
      this.scene = this.experience.mainScene;
      this.state = this.experience.state;
    }
    setInstance() {
      this.clearColor = "#010101";
      this.instance = new WebGPURenderer({
        canvas: this.canvas,
        //powerPreference: "high-performance",
        antialias: true,
        //samples: 4,
        alpha: false,
        stencil: false,
        depth: true,
        useLegacyLights: false,
        physicallyCorrectLights: true,
        forceWebGL: false
      });
      this.instance.outputColorSpace = SRGBColorSpace;
      this.instance.setSize(this.sizes.width, this.sizes.height);
      this.instance.setPixelRatio(Math.min(this.sizes.pixelRatio, 2));
      this.instance.setClearColor(this.clearColor, 1);
      this.instance.setSize(this.sizes.width, this.sizes.height);
    }
    setDebug() {
      if (this.debug.active) {
        if (this.debug.panel) {
          const debugFolder = this.debug.panel.addFolder({
            title: "Renderer",
            expanded: false
          });
          debugFolder.addBinding(this.instance, "toneMapping", {
            label: "Tone Mapping",
            options: {
              "No": NoToneMapping,
              "Linear": LinearToneMapping,
              "Reinhard": ReinhardToneMapping,
              "Cineon": CineonToneMapping,
              "ACESFilmic": ACESFilmicToneMapping,
              "AgXToneMapping": AgXToneMapping,
              "NeutralToneMapping": NeutralToneMapping
            }
          }).on("change", () => {
            if (this.state.postprocessing) {
              this.experience.postProcess.composer.needsUpdate = true;
            }
          });
          debugFolder.addBinding(this.instance, "toneMappingExposure", {
            min: 0,
            max: 2,
            step: 0.01,
            label: "Tone Mapping Exposure"
          });
        }
      }
    }
    update() {
      if (this.debug.active) {
        this.debugRender();
      } else {
        this.productionRender();
      }
    }
    productionRender() {
      this.instance.renderAsync(this.scene, this.camera);
    }
    debugRender() {
      this.instance.renderAsync(this.scene, this.camera);
    }
    resize() {
      this.instance.setSize(this.sizes.width, this.sizes.height);
      this.instance.setPixelRatio(this.sizes.pixelRatio);
    }
    destroy() {
    }
  };

