  // source/src/Experience/Utils/Resources.js
  var Resources2 = class extends EventEmitter {
    constructor(sources) {
      super();
      this.sources = sources;
      this.items = {};
      this.toLoad = this.sources.length;
      this.loaded = 0;
      this.loadedAll = false;
      this.setLoaders();
      this.startLoading();
    }
    sourcesFilter() {
      if (define_import_meta_env_default.MODE === "development") {
        return true;
      }
      this.sources.forEach((source) => {
        if (source.obfuscate === true) {
          if (source.type.match(/model/i)) {
            source.path = source.path.replace(/\.(glb|gltf|obj)/i, ".bin");
            source.type = "binModel";
          }
          if (source.type === "json") {
            source.path = source.path.replace(/\.(json)/i, ".bin");
            source.type = "binJson";
          }
          if (source.type.match(/texture/i)) {
            source.path = source.path.replace(/\.(jpg|jpeg|png)/i, ".bin");
            source.type = "binTexture";
          }
        }
      });
    }
    setLoaders() {
      this.loaders = {};
      this.loaders.gltfLoader = new GLTFLoader();
      this.loaders.objLoader = new OBJLoader();
      this.loaders.textureLoader = new TextureLoader();
      this.loaders.cubeTextureLoader = new CubeTextureLoader();
      this.loaders.RGBELoader = new RGBELoader();
      this.loaders.fontLoader = new FontLoader();
      this.loaders.AudioLoader = new AudioLoader();
      const dracoLoader = new DRACOLoader();
      dracoLoader.setDecoderPath("/draco/");
      const ktx2Loader = new KTX2Loader();
      ktx2Loader.setTranscoderPath("/basis/");
      this.loaders.gltfLoader.setDRACOLoader(dracoLoader);
      this.loaders.gltfLoader.setKTX2Loader(ktx2Loader);
      this.loaders.gltfLoader.setMeshoptDecoder(MeshoptDecoder);
    }
    startLoading() {
      for (const source of this.sources) {
        switch (source.type) {
          case "binModel":
            this.obfuscate.loadFile(source.path, (arrayBuffer3) => {
              this.obfuscate.decode(arrayBuffer3, source.path, (model) => {
                this.sourceLoaded(source, model);
              });
            });
            break;
          case "binJson":
            this.obfuscate.loadFile(source.path, (arrayBuffer3) => {
              this.obfuscate.decode(arrayBuffer3, source.path, (json) => {
                this.sourceLoaded(source, json);
              });
            });
            break;
          case "binTexture":
            this.obfuscate.loadFile(source.path, (arrayBuffer3) => {
              this.obfuscate.decode(arrayBuffer3, source.path, (textureBuffer) => {
                const blob = new Blob([textureBuffer]);
                createImageBitmap(blob).then((imageBitmap) => {
                  const texture3 = new Texture(imageBitmap);
                  texture3.needsUpdate = true;
                  this.sourceLoaded(source, texture3);
                }).catch((err) => console.error("Error texture loading:", err));
              });
            });
            break;
          case "gltfModel":
            this.loaders.gltfLoader.load(
              source.path,
              (file) => {
                this.sourceLoaded(source, file);
              }
            );
            break;
          case "objModel":
            this.loaders.objLoader.load(
              source.path,
              (file) => {
                this.sourceLoaded(source, file);
              }
            );
            break;
          case "texture":
            this.loaders.textureLoader.load(
              source.path,
              (file) => {
                this.sourceLoaded(source, file);
              }
            );
            break;
          case "videoTexture":
            let videoElement = document.createElement("video");
            videoElement.src = source.path;
            videoElement.setAttribute("crossorigin", "anonymous");
            videoElement.muted = true;
            videoElement.loop = true;
            videoElement.load();
            videoElement.setAttribute("playsinline", "");
            videoElement.setAttribute("webkit-playsinline", "");
            videoElement.play();
            const obj = {
              videoTexture: new VideoTexture(videoElement),
              videoElement
            };
            videoElement.addEventListener("canplaythrough", () => {
              this.sourceLoaded(source, obj);
            });
            break;
          case "cubeTexture":
            this.loaders.cubeTextureLoader.load(
              source.path,
              (file) => {
                this.sourceLoaded(source, file);
              }
            );
            break;
          case "rgbeTexture":
            this.loaders.RGBELoader.load(
              source.path,
              (file) => {
                this.sourceLoaded(source, file);
              }
            );
            break;
          case "font":
            this.loaders.fontLoader.load(
              source.path,
              (file) => {
                this.sourceLoaded(source, file);
              }
            );
            break;
          case "audio":
            this.loaders.AudioLoader.load(
              source.path,
              (file) => {
                this.sourceLoaded(source, file);
              }
            );
            break;
          case "json":
            fetch(source.path).then(
              (response) => {
                response.json().then(
                  (data) => {
                    this.sourceLoaded(source, data);
                    return data;
                  }
                );
              }
            );
            break;
        }
      }
      if (this.sources.length === 0) {
        setTimeout(() => {
          this.loadedAll = true;
          this.trigger("ready");
        });
      }
    }
    sourceLoaded(source, file) {
      this.items[source.name] = file;
      this.loaded++;
      if (this.loaded === this.toLoad) {
        this.loadedAll = true;
        this.trigger("ready");
      }
    }
  };

